INSERT INTO foodme.chef (id, username, phone_number, email, avatar_url, banner_url, status, full_name_en, full_name_am, full_name_ru, description_en, description_am, description_ru, kitchen_en, kitchen_am, kitchen_ru, rating, platform_fee, delivery_price, free_delivery_from, priority_index) VALUES (28, 'bourbon_yerevan', '+37499110005', 'chef5@example.com', 'https://static.bychef.am/chefs/28/avatar.jpg', NULL, 'ACTIVE', 'Lilit Mkrtchyan', 'Լիլիթ Մկրտչյան', 'Лилит Мкртчян', 'Pastries and semi-finished products made with natural ingredients and always fresh. Suitable for both everyday hunger and festive table.', 'Բնական բաղադրիչներով և մշտապես թարմ խմորեղեն և կիսաֆաբրիկատներ։ Հարմար է թե առօրյա քաղցը բավարարելու, թե տոնական սեղանի համար։', 'Всегда свежая выпечка и полуфабрикаты из натуральных ингредиентов. Подходит как для утоления повседневного голода, так и для праздничного стола.', 'Bourbon_yerevan', 'Bourbon_yerevan', 'Bourbon_yerevan', 0, 7, 500.0, 5000.0, 34);
